package net.e175.klaus.solarpositioning;

import org.junit.Test;
import static org.hamcrest.MatcherAssert.assertThat;
import static org.hamcrest.Matchers.is;
import java.time.LocalDate;
import static java.lang.Math.pow;

public class DeltaTTest {

    @Test
    public void estimate_DifferentDate_ReturnsDifferentValue() {
        LocalDate forDate1 = LocalDate.of(2022, 6, 21);
        LocalDate forDate2 = LocalDate.of(2022, 7, 20);
        assertThat(DeltaT.estimate(forDate1), is(not(DeltaT.estimate(forDate2))));
    }

    @Test
    public void estimate_SameDayDifferentTime_ReturnsSameValue() {
        LocalDate forDate = LocalDate.of(2022, 6, 21);
        double valueAt12 = DeltaT.estimate(forDate.atStartOfDay());
        double valueAt23 = DeltaT.estimate(forDate.atTime(23));
        assertThat(valueAt12, is(not(DeltaT.estimate(forDate.atTime(23))));
    }

    @Test
    public void estimate_ValidYear_ReturnsValidValue() {
        LocalDate forDate = LocalDate.of(2022, 6, 21);
        double value = DeltaT.estimate(forDate);
        assertThat(value >= -1, is(true));
        assertThat(value <= 24, is(true));
    }

    @Test
    public void estimate_InvalidYear_ReturnsZero() {
        LocalDate forDate = LocalDate.of(0, 6, 21);
        double value = DeltaT.estimate(forDate);
        assertThat(value, is(0));
    }
}
